package com.bank.approval;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class ApprovalBracketGenerator {

    private static final Logger log = Logger.getLogger(ApprovalBracketGenerator.class.getName());

    public List<String> generate(int n) {
        List<String> result = new ArrayList<>();
        backtrack(n, 0, 0, new StringBuilder(), result);
        log.info(() -> "Generated " + result.size() + " balanced bracket templates for n=" + n);
        return result;
    }

    private void backtrack(int n, int open, int close, StringBuilder sb, List<String> result) {
        if (sb.length() == 2 * n) { result.add(sb.toString()); return; }
        if (open < n) {                        // can still open
            sb.append('(');
            backtrack(n, open + 1, close, sb, result);
            sb.deleteCharAt(sb.length() - 1);
        }
        if (close < open) {                    // can close only if one is open
            sb.append(')');
            backtrack(n, open, close + 1, sb, result);
            sb.deleteCharAt(sb.length() - 1);
        }
    }
}
